    def inter_relocate(rs, loads):
        R = len(rs)
        if R < 2:
            return False
        improved = False
        # Deterministic loops: from route 0..R-1
        # We'll try moving from rid_a to rid_b by inserting at either end of target.
        current_total = total_cost(rs)
        # To reduce runtime, limit number of evaluated moves based on size
        max_moves = 2000 if sum(len(x) for x in rs) > 120 else 800
        evals = 0

        # Precompute route costs once
        rcost = [route_cost(rt) for rt in rs]

        # helper to compute new cost for rid_a after removing position p
        def cost_remove(rt, p):
            if len(rt) == 1:
                return d(depot, rt[0]) + d(rt[0], depot)  # before
            if p == 0:
                # before: depot->x0->x1.. ; after connects depot->x1
                return (d(rt[0], rt[1]) + d(depot, rt[0]))  # will subtract/replace carefully not used
            return 0

        # Instead of complicated deltas, do localized delta using edges.
        def delta_remove(rt, p):
            m = len(rt)
            x = rt[p]
            if m == 1:
                return -(d(depot, x) + d(x, depot))
            if p == 0:
                y = rt[1]
                # remove edges depot-x and x-y, add depot-y
                return (d(depot, y) - (d(depot, x) + d(x, y)))
            if p == m - 1:
                y = rt[m - 2]
                return (d(y, depot) - (d(y, x) + d(x, depot)))
            y = rt[p - 1]
            z = rt[p + 1]
            # remove y-x and x-z, add y-z
            return (d(y, z) - (d(y, x) + d(x, z)))

        def delta_insert_at_front(rt, node):
            m = len(rt)
            if m == 0:
                return route_cost([node])
            first = rt[0]
            # remove edge depot-first, add depot-node and node-first
            return (d(depot, node) + d(node, first) - (d(depot, first)))

        def delta_insert_at_back(rt, node):
            m = len(rt)
            if m == 0:
                return route_cost([node])
            last = rt[-1]
            return (d(last, node) + d(node, depot) - (d(last, depot)))

        best = None  # (delta_total, a, b, pos, side)
        best_delta_total = 0

        for a in range(R):
            ra = rs[a]
            ma = len(ra)
            if ma == 0:
                continue
            # try moving each customer but cap evals
            for p in range(ma):
                node = ra[p]
                # Consider targets
                for b in range(R):
                    if b == a:
                        continue
                    if loads[b] + demands[node] > cap:
                        continue
                    # Insert at front
                    if evals >= max_moves:
                        break
                    # delta_total = delta_a_remove + delta_b_insert
                    delta_a = delta_remove(ra, p)
                    delta_b = delta_insert_at_front(rs[b], node)
                    delta_total = delta_a + delta_b
                    evals += 1
                    if delta_total < best_delta_total:
                        best_delta_total = delta_total
                        best = (a, b, p, 0)
                    # Insert at back
                    if evals >= max_moves:
                        break
                    delta_b = delta_insert_at_back(rs[b], node)
                    delta_total = delta_a + delta_b
                    evals += 1
